package main

// SHIPPED COMPLETION SCRIPTS (U37).
//
// scripts/release-dist.sh puts completions/{pulse.bash,_pulse,pulse.fish}
// into every release archive, generated by scripts/release-completions.sh
// from a host build. TestCompletion_ShippedScriptsMatchLeaf drives that
// same generation script against this test binary (re-executed as the
// CLI via TestMain) and pins each file byte-equal to the leaf's output,
// with one file per shell CompletionShells() names.

import (
	"bytes"
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"testing"

	pcli "github.com/frankbardon/pulse/internal/cli"
)

// runAsCLIEnv, when "1", makes the test binary act as the pulse CLI so a
// shell script under test can invoke it as PULSE without a build.
const runAsCLIEnv = "CMD_PULSE_TEST_RUN_AS_CLI"

func TestMain(m *testing.M) {
	if os.Getenv(runAsCLIEnv) == "1" {
		args := append([]string{"pulse"}, os.Args[1:]...)
		os.Exit(run(context.Background(), args, os.Stdout, os.Stderr))
	}
	os.Exit(m.Run())
}

// shippedCompletionFiles maps each supported shell to the file the
// release archives carry under completions/.
var shippedCompletionFiles = map[string]string{
	"bash": "pulse.bash",
	"zsh":  "_pulse",
	"fish": "pulse.fish",
}

func TestCompletion_ShippedScriptsMatchLeaf(t *testing.T) {
	if _, err := exec.LookPath("bash"); err != nil {
		t.Fatalf("bash is required to exercise scripts/release-completions.sh: %v", err)
	}

	shells := pcli.CompletionShells()
	var mapped []string
	for sh := range shippedCompletionFiles {
		mapped = append(mapped, sh)
	}
	slices.Sort(mapped)
	want := slices.Sorted(slices.Values(shells))
	if !slices.Equal(mapped, want) {
		t.Fatalf("shipped completion files cover shells %v, CompletionShells() = %v", mapped, want)
	}

	self, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	out := t.TempDir()
	cmd := exec.Command("bash", filepath.Join("..", "..", "scripts", "release-completions.sh"), out, self)
	cmd.Env = append(os.Environ(), runAsCLIEnv+"=1")
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("release-completions.sh: %v\n%s", err, stderr.String())
	}

	entries, err := os.ReadDir(out)
	if err != nil {
		t.Fatal(err)
	}
	var got []string
	for _, e := range entries {
		got = append(got, e.Name())
	}
	var wantFiles []string
	for _, f := range shippedCompletionFiles {
		wantFiles = append(wantFiles, f)
	}
	slices.Sort(got)
	slices.Sort(wantFiles)
	if !slices.Equal(got, wantFiles) {
		t.Fatalf("generated files = %v, want %v", got, wantFiles)
	}

	for _, sh := range shells {
		var leaf, leafErr bytes.Buffer
		if status := run(context.Background(), []string{"pulse", "completion", sh}, &leaf, &leafErr); status != 0 {
			t.Fatalf("pulse completion %s: status %d: %s", sh, status, leafErr.String())
		}
		shipped, err := os.ReadFile(filepath.Join(out, shippedCompletionFiles[sh]))
		if err != nil {
			t.Fatal(err)
		}
		if leaf.Len() == 0 {
			t.Fatalf("pulse completion %s printed nothing", sh)
		}
		if !bytes.Equal(shipped, leaf.Bytes()) {
			t.Errorf("completions/%s differs from `pulse completion %s` output", shippedCompletionFiles[sh], sh)
		}
	}
}
